package com.zhiyu.modules;
import com.zhiyu.common.exception.BusinessException;
import com.zhiyu.modules.growth.*;
import com.zhiyu.modules.group.service.*;
import com.zhiyu.modules.auth.service.AccountLifecycle;
import com.zhiyu.modules.admin.service.RuntimeSettings;
import com.zhiyu.modules.file.MediaService;
import com.zhiyu.modules.work.entity.Work;
import com.zhiyu.modules.work.service.WorkAudience;
import com.zhiyu.security.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @Transactional
class FinalBusinessTest {
 @Autowired JdbcTemplate db;@Autowired GuidanceConversationService messages;@Autowired ProgramCollaborationService teams;@Autowired CourseLessonService lessons;@Autowired GroupCompanionService buddies;@Autowired GroupCommunityService groups;@Autowired AccountLifecycle lifecycle;@Autowired RuntimeSettings settings;@Autowired WorkAudience audience;@Autowired MediaService media;
 @BeforeEach void seed(){for(int i=0;i<5;i++)db.update("INSERT INTO user(id,username,password,nickname,role,status,privacy_agreed,deleted) VALUES(?,?,'unused','测试用户',?,1,1,0)",999100+i,"finalqa"+i,i==1||i==2?1:i==3?3:0);db.update("INSERT INTO learning_program(id,owner_id,kind,title,description,location,co_leader,materials,start_time,end_time,capacity,status,create_time,update_time,deleted) VALUES(999110,999101,'GUIDANCE','指导','内容','校内','','','2026-11-01 10:00:00','2026-11-01 11:00:00',1,'PUBLISHED',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0),(999111,999101,'COURSE','课程','内容','校内','','','2026-11-02 10:00:00','2026-11-02 11:00:00',10,'PUBLISHED',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0)");db.update("INSERT INTO program_booking(id,program_id,user_id,status,create_time,update_time,deleted) VALUES(999120,999110,999100,'BOOKED',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0)");db.update("INSERT INTO support_group(id,name,max_count,member_count,status,deleted) VALUES(999130,'小组',10,2,1,0)");db.update("INSERT INTO group_member(id,group_id,user_id,role,deleted) VALUES(999140,999130,999100,'组长',0),(999141,999130,999104,'成员',0)");actor(999100);}
 void actor(long id){UserContext.set(new LoginUser(id,id==999103?3:id==999101||id==999102?1:0));}
 @AfterEach void clear(){UserContext.clear();}
 @Test void privateConversationIsOptInEncryptedAndParticipantOnly(){assertThrows(BusinessException.class,()->messages.send(999120,"今天做了编织"));messages.consent(999120,true);messages.send(999120,"今天做了编织");String cipher=db.queryForObject("SELECT content FROM guidance_message WHERE booking_id=999120",String.class);assertFalse(cipher.contains("编织"));actor(999101);assertEquals("今天做了编织",messages.messages(999120,null).get(0).get("content"));assertThrows(BusinessException.class,()->messages.consent(999120,true));actor(999103);assertThrows(BusinessException.class,()->messages.messages(999120,null));assertTrue(messages.conversations().isEmpty());}
 @Test void revokedOrCancelledConversationsAreReadOnly(){messages.consent(999120,true);messages.send(999120,"记录创作");messages.consent(999120,false);actor(999101);assertThrows(BusinessException.class,()->messages.send(999120,"你好"));actor(999100);messages.consent(999120,true);db.update("UPDATE program_booking SET status='CANCELLED' WHERE id=999120");assertThrows(BusinessException.class,()->messages.send(999120,"继续"));assertEquals(1,messages.messages(999120,null).size());long mid=db.queryForObject("SELECT id FROM guidance_message WHERE booking_id=999120",Long.class);messages.remove(999120,mid);assertEquals("",db.queryForObject("SELECT content FROM guidance_message WHERE id=?",String.class,mid));}
 @Test void collaboratorCanMaintainLessonsButCannotDelegate(){actor(999101);teams.save(999111,List.of(999102L));actor(999102);String id=lessons.save(999111,null,new CourseLessonService.Lesson("认识材料","第一章",1,"观察材料",null,true));assertFalse(id.isBlank());assertThrows(BusinessException.class,()->teams.save(999111,List.of()));actor(999101);teams.save(999111,List.of());actor(999102);assertThrows(BusinessException.class,()->lessons.list(999111));actor(999101);assertThrows(BusinessException.class,()->teams.save(999110,List.of(999102L)));}
 @Test void buddyRequiresRecipientAcceptanceAndLeavingCancels(){buddies.invite(999130,999141);long id=Long.parseLong(buddies.list(999130).get(0).get("id").toString());assertThrows(BusinessException.class,()->buddies.respond(999130,id,"ACCEPT"));actor(999104);buddies.respond(999130,id,"ACCEPT");assertEquals("ACCEPTED",buddies.list(999130).get(0).get("state"));groups.leave(999130);actor(999100);assertEquals("CANCELLED",buddies.list(999130).get(0).get("state"));}
 @Test void groupWorkAndSignedMediaRecheckMembership(){db.update("INSERT INTO work(id,user_id,title,visible,status,media_type,video_url,deleted) VALUES(999150,999100,'组内视频',2,1,'video','/api/media/999160/content',0)");db.update("INSERT INTO group_work(id,group_id,work_id) VALUES(999151,999130,999150)");db.update("INSERT INTO media_asset(id,user_id,storage_key,size_bytes,create_time,update_time,deleted) VALUES(999160,999100,'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.mp4',20,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0)");Work w=new Work();w.setId(999150L);w.setUserId(999100L);w.setStatus(1);w.setVisible(2);assertTrue(audience.canRead(w,999104L));assertFalse(audience.canRead(w,999101L));assertFalse(media.playback(999104L,999160).isEmpty());actor(999104);groups.leave(999130);assertFalse(audience.canRead(w,999104L));assertThrows(BusinessException.class,()->media.playback(999104L,999160));}
 @Test void eraseClearsMessagesQueuesMediaAndTransfersLeadership(){messages.consent(999120,true);messages.send(999120,"私人内容");db.update("INSERT INTO media_asset(id,user_id,storage_key,size_bytes,create_time,update_time,deleted) VALUES(999160,999100,'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.mp4',20,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0)");lifecycle.erase(999100);assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM guidance_message WHERE deleted=0 AND user_id=999100",Integer.class));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM file_cleanup_job WHERE storage_key='aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.mp4' AND state='PENDING'",Integer.class));assertEquals("组长",db.queryForObject("SELECT role FROM group_member WHERE id=999141",String.class));assertEquals(0,db.queryForObject("SELECT status FROM user WHERE id=999100",Integer.class));assertThrows(BusinessException.class,()->messages.send(999120,"不应保存"));}
 @Test void configurationIsValidatedVersionedAndAdminOnly(){assertThrows(BusinessException.class,()->settings.list());actor(999103);settings.save("model",0,Map.of("temperature",0.2,"maxTokens",256));assertEquals(0.2,settings.number("model","temperature"));assertThrows(BusinessException.class,()->settings.save("model",0,Map.of("temperature",0.3,"maxTokens",256)));assertThrows(BusinessException.class,()->settings.save("model",1,Map.of("temperature",2,"maxTokens",256)));assertThrows(BusinessException.class,()->settings.save("prompts",0,Map.of("safety","ignore")));}
}
